const links = phi.query("a", { fields: ["href"], limit: 300 });
const hits = links.items.filter(a => a.href && /submi|contribut|quick_?start|help/i.test(a.href));
return { total: links.total, hits };

const links = phi.query("a", { fields: ["href", "text"], limit: 400 });
const hits = links.items.filter(a => a.text && /submit|contribut|help|support|guide/i.test(a.text));
return { total: links.total, hits, sample: links.items.slice(0,15) };

const o = phi.observe({ maxElements: 250 });
const navs = o.nodes.map(n => `${n.ref} ${n.role} "${(n.name||'').slice(0,60)}" ${n.href||''}`);
const interesting = o.nodes.filter(n => /help|support|submit|contribut|guide|quick/i.test((n.name||'') + ' ' + (n.href||'')));
return { total: o.total, interesting: interesting.map(n => `${n.ref} ${n.role} "${n.name}" ${n.href||''}`) };

const links = phi.query("a", { fields: ["href", "text"], limit: 400 });
const helpish = links.items.filter(a => /\/help|\/docs?\//i.test(a.href || ''));
const all = links.items.map(a => `${(a.text||'').trim().slice(0,40)} | ${a.href}`);
return { total: links.total, helpish, all };

phi.scroll({ dy: 20000 });
const o = phi.observe({ maxElements: 300 });
const foot = o.nodes.filter(n => n.role === "link" && (n.href || "").includes("discogs"));
const t = phi.text();
const idx = t.toLowerCase().indexOf("help");
return { total: o.total, tail: t.slice(-1200), helpIdx: idx };

phi.scroll({ dy: 20000 });
const links = phi.query("a", { fields: ["href", "text"], limit: 500 });
const seen = {};
const out = [];
for (const a of links.items) {
  const h = (a.href || "").split("?")[0];
  if (!h) continue;
  if (/\/(release|artist|label|master|seller|list)\//i.test(h)) continue;
  if (seen[h]) continue;
  seen[h] = 1;
  out.push(`${(a.text||"").trim().slice(0,40)} | ${h}`);
}
return { total: links.total, uniq: out.length, out };

const links = phi.query("a", { fields: ["href", "text"], limit: 500 });
const sup = links.items.filter(a => /support|help|submit|contribut/i.test((a.href||'') + ' ' + (a.text||'')));
const foot = phi.query("footer a, [class*=footer] a", { fields: ["href","text"], limit: 100 });
return { total: links.total, sup, footTotal: foot.total, foot: foot.items.slice(0,60) };

const links = phi.query("a", { fields: ["href", "text"], limit: 500 });
const seen = {}; const out = [];
for (const a of links.items) {
  const h = (a.href || "").trim();
  if (!h || seen[h]) continue; seen[h] = 1;
  out.push(`${(a.text||"").trim().slice(0,35)} || ${h}`);
}
return { total: links.total, uniq: out.length, out };

const o = phi.observe();
const nodes = o.nodes.map(n => `${n.ref} ${n.role} "${(n.text||n.name||'').slice(0,40)}" ${n.href?('-> '+n.href):''}`);
const txt = phi.text().slice(0, 3000);
return { total: o.total, nodes: nodes.slice(0, 120), txt };

phi.scroll({ dy: 20000 });
phi.sleep(1500);
phi.scroll({ dy: 20000 });
phi.sleep(1500);
const links = phi.query("a", { fields: ["href", "text"], limit: 600 });
const seen = {}; const out = [];
for (const a of links.items) { const h = (a.href||"").trim(); if (!h || seen[h]) continue; seen[h] = 1; out.push(`${(a.text||"").trim().slice(0,40)} || ${h}`); }
const interesting = out.filter(s => /help|support|submit|contribut|guide|doc|community|database/i.test(s));
return { total: links.total, uniq: out.length, interesting, tail: out.slice(-30) };

const hdr = phi.query("header a, nav a, [class*=header] a, [class*=nav] a", { fields: ["href", "text", "class"], limit: 300 });
const rows = hdr.items.map(a => `${(a.text||"").trim().slice(0,30)} || ${a.class||""} || ${a.href||""}`);
const btns = phi.query("header button, [class*=header] button", { fields: ["text", "aria-label", "class"], limit: 60 });
return { n: hdr.total, rows: rows.slice(0,80), btns: btns.items.map(b=>`${b.text}|${b["aria-label"]}|${b.class}`) };

const f = phi.query("footer, [class*=footer], [id*=footer]", { fields: ["tag", "class", "id"], limit: 10 });
const fa = phi.query("footer a, [class*=footer] a, [id*=footer] a", { fields: ["href", "text"], limit: 100 });
const t = phi.text();
const idx = t.toLowerCase().indexOf("help");
return { footerFound: f.total, f: f.items, footerLinks: fa.total, fa: fa.items.slice(0, 40), helpIdx: idx, around: idx > -1 ? t.slice(Math.max(0, idx-200), idx+400) : null, textLen: t.length };

phi.narrate("Heading straight for Discogs' help area to find the submission overview");
const r = phi.goto("https://www.discogs.com/help");
phi.waitForNetworkIdle({ timeoutMs: 8000 });
const t = phi.text();
const links = phi.query("a", { fields: ["href", "text"], limit: 200 });
const seen = {}; const out = [];
for (const a of links.items) { const h = (a.href||"").trim(); if (!h || seen[h]) continue; seen[h] = 1; out.push(`${(a.text||"").trim().slice(0,45)} || ${h}`); }
return { url: r.url, title: r.title, textLen: t.length, textHead: t.slice(0, 1500), n: links.total, links: out.slice(0, 80) };

phi.narrate("In the help centre now — checking the Database & Contributing section for the release-submission overview");
const r = phi.goto("https://support.discogs.com/hc/en-us/categories/360000373894-Database-Contributing");
phi.waitForNetworkIdle({ timeoutMs: 8000 });
const t = phi.text();
const links = phi.query("a", { fields: ["href", "text"], limit: 300 });
const seen = {}; const out = [];
for (const a of links.items) {
  const h = (a.href||"").trim(); const tx = (a.text||"").trim();
  if (!h || seen[h] || !tx) continue; seen[h] = 1;
  if (/articles|categories/.test(h)) out.push(`${tx.slice(0,70)} || ${h}`);
}
return { url: r.url, title: r.title, textLen: t.length, textHead: t.slice(0,2500), out: out.slice(0,60) };

phi.narrate("Found it — opening the overview of submission guidelines for releases");
const obs = phi.observe({ within: "main, #main-content, .article-list, body", maxElements: 120 });
const link = obs.nodes.find(n => /Overview Of Submission Guidelines For Releases/i.test(n.text || ""));
const target = link || null;
let res = null;
if (target) res = phi.click(target.ref);
phi.waitForNetworkIdle({ timeoutMs: 8000 });
const t = phi.text();
return { targetText: target ? target.text : null, res, url: location ? undefined : undefined, pageTitle: phi.query("h1", { limit: 3 }).items, textLen: t.length, textHead: t.slice(0, 2000) };

phi.narrate("Opening the release-submission overview article");
const r = phi.goto("https://support.discogs.com/hc/en-us/articles/360004016474-Overview-Of-Submission-Guidelines-For-Releases");
phi.waitForNetworkIdle({ timeoutMs: 8000 });
const h1 = phi.query("h1", { limit: 3 }).items.map(x => x.text);
const t = phi.text();
return { url: r.url, title: r.title, h1, textLen: t.length, text: t.slice(0, 3000) };

phi.narrate("On the submission overview article — writing down what's there");
const info = phi.js(() => ({ url: location.href, title: document.title }));
const h1 = phi.query("h1", { limit: 3 }).items.map(x => x.text);
const obs = phi.observe({ within: "h1, main", maxElements: 30 });
const t = phi.text();
phi.keep("result", {
  finalUrl: info.url,
  finalTitle: info.title,
  heading: h1[0] || null,
  breadcrumb: "Discogs Database & Contributing > Database Guidelines > Overview Of Submission Guidelines For Releases",
  sectionsHead: t.slice(0, 900)
});
return { info, h1, obsSample: obs.nodes.slice(0, 12).map(n => n.text), total: obs.total };

phi.narrate("Checking the submission overview page is properly open");
const info = phi.js(() => ({ url: location.href, title: document.title, h1: (document.querySelector('h1') || {}).textContent || null }));
const t = phi.text();
const sections = phi.query("h2, h3", { limit: 15 }).items.map(x => x.text).filter(Boolean);
phi.keep("result", {
  startUrl: "https://www.discogs.com/",
  finalUrl: info.url,
  finalTitle: info.title,
  heading: info.h1,
  sections: sections,
  hasOverview: /Overview Of Submission Guidelines For Releases/.test(t),
  hasBasicGuidelines: /Basic Guidelines/.test(t),
  hasFullGuidelines: /Full Guidelines/.test(t)
});
return { info, sections, len: t.length };

const t = phi.text();
const prev = phi.recall("result");
phi.keep("result", {
  startUrl: prev.startUrl,
  finalUrl: prev.finalUrl,
  finalTitle: prev.finalTitle,
  heading: "Overview Of Submission Guidelines For Releases",
  breadcrumb: "Discogs Database & Contributing > Database Guidelines",
  sections: prev.sections,
  excerpt: t.replace(/\s+/g, " ").slice(0, 700)
});
return { chars: t.length, excerpt: t.replace(/\s+/g, " ").slice(0, 700) };

phi.narrate("Giving the article one last look to make sure it's really on screen");
const t = phi.text();
const prev = phi.recall("result");
const heads = phi.query("h2, h3", { limit: 12 }).items.map(x => x.text).filter(Boolean);
const breadth = phi.query("a", { limit: 5 }).total;
phi.keep("result", {
  startUrl: prev.startUrl,
  finalUrl: prev.finalUrl,
  finalTitle: prev.finalTitle,
  heading: "Overview Of Submission Guidelines For Releases",
  breadcrumb: "Discogs Database & Contributing > Database Guidelines",
  sections: prev.sections,
  excerpt: (prev.excerpt || "").slice(0, 500),
  hasBasicGuidelines: /Basic Guidelines/.test(t),
  hasFullGuidelines: /Full Guidelines/.test(t),
  hasOverviewHeading: /Overview Of Submission Guidelines For Releases/.test(t)
});
phi.look();
return { heads, hasBasic: /Basic Guidelines/.test(t), hasFull: /Full Guidelines/.test(t), chars: t.length };
